cat > /tmp/shot.mjs <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const [file, out, mode, w, h] = process.argv.slice(2);
const PORT = 9700 + (process.pid % 200);
const profile = mkdtempSync(join(tmpdir(), 'shot-'));
const chrome = spawn('google-chrome', ['--headless=new', `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${profile}`, '--no-sandbox', '--disable-gpu', `--window-size=${w},${h}`, 'about:blank'], { stdio: 'ignore' });
const sleep = ms => new Promise(r => setTimeout(r, ms));
let wsUrl;
for (let i = 0; i < 50; i++) {
  try { const l = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
    const p = l.find(t => t.type === 'page'); if (p) { wsUrl = p.webSocketDebuggerUrl; break; } } catch {}
  await sleep(200);
}
const ws = new WebSocket(wsUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map();
ws.onmessage = ev => { const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id);
    m.error ? p.reject(new Error(m.error.message)) : p.resolve(m.result); } };
const send = (method, params = {}) => { const i = ++id; ws.send(JSON.stringify({ id: i, method, params }));
  return new Promise((resolve, reject) => pending.set(i, { resolve, reject })); };

await send('Page.enable'); await send('Runtime.enable');
await send('Page.navigate', { url: pathToFileURL(file).href });
await sleep(600);
if (mode === 'wizard') {
  await send('Runtime.evaluate', { expression: `document.querySelector('[data-open-wizard]').click()` });
  await sleep(400);
} else if (mode === 'result') {
  await send('Runtime.evaluate', { expression: `document.querySelector('[data-open-wizard]').click()` });
  await sleep(300);
  await send('Runtime.evaluate', { expression: `for (let i=0;i<7;i++) document.querySelector('[data-disc-next]').click(); document.querySelector('[data-disc-finish]').click()` });
  await sleep(600);
} else if (mode === 'step1') {
  await send('Runtime.evaluate', { expression: `document.querySelector('[data-open-wizard]').click()` });
  await sleep(300);
  await send('Runtime.evaluate', { expression: `document.querySelector('[data-disc-next]').click()` });
  await sleep(300);
}
const { data } = await send('Page.captureScreenshot', { format: 'png' });
writeFileSync(out, Buffer.from(data, 'base64'));
ws.close(); chrome.kill('SIGKILL'); rmSync(profile, { recursive: true, force: true });
console.log('saved', out);
