await sleep(300);
// начать drag и оставить в середине
const r = await send('Runtime.evaluate', { expression: `(function () {
  const ul = document.getElementById('draggable-list1');
  const first = ul.children[0];
  const last = ul.children[3];
  const r1 = first.getBoundingClientRect(), r2 = last.getBoundingClientRect();
  const opt = (x, y) => ({ bubbles: true, cancelable: true, pointerId: 3, pointerType: 'mouse',
    clientX: x, clientY: y, button: 0, buttons: 1, isPrimary: true });
  first.dispatchEvent(new PointerEvent('pointerdown', opt(r1.left + 30, r1.top + r1.height / 2)));
  window.dispatchEvent(new PointerEvent('pointermove', opt(r1.left + 120, r1.top + 60)));
  window.dispatchEvent(new PointerEvent('pointermove', opt(r2.left + 150, r2.top + r2.height - 10)));
  return document.querySelectorAll('.disc-clone').length;
})()` });
console.log('clones in flight:', r.result.value);
await sleep(150);
const { data } = await send('Page.captureScreenshot', { format: 'png' });
writeFileSync(process.argv[3], Buffer.from(data, 'base64'));
// завершить drag
await send('Runtime.evaluate', { expression: `window.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, pointerId: 3, pointerType: 'mouse', button: 0, buttons: 0 }))` });
await sleep(200);
const after = await send('Runtime.evaluate', { expression: `document.querySelectorAll('.disc-clone').length + '|' + Array.from(document.getElementById('draggable-list1').children).map(l => l.textContent.trim()).join(',')` });
console.log('after drop:', after.result.value);
ws.close(); chrome.kill('SIGKILL'); rmSync(profile, { recursive: true, force: true });
